import {advancedDefinition,advancedValue,abilityEvolutionOptions} from './advanced-powers.mjs';
import {applyStatus,statusModifiers} from './statuses.mjs';
const keys={strength:'skill',agility:'insight',intelligence:'control',charisma:'charisma'};
export function abilityProfiles(s){const out=[];for(const id of s.passiveLoadout||[]){if(!s.passiveSkills?.includes(id))continue;const evolved=abilityEvolutionOptions(id).find(e=>e.id===s.powerEvolutions?.[id]),base=advancedDefinition(id);if(evolved)out.push({id,name:evolved.name,p:evolved.profile,v:1});else if(base)out.push({id,name:base.name,p:base.profile,v:advancedValue(s,id)});}const core=abilityEvolutionOptions('core-breath').find(e=>e.id===s.powerEvolutions?.['core-breath']);if(core)out.push({id:'core-breath',name:core.name,p:core.profile,v:1});return out;}
function state(s){const a=s.battle.abilityState??={concentration:0};a.attributes??={};a.reduction??=0;a.armor??=0;a.vulnerable??=0;a.haste??=0;a.bonusActions??=0;a.opening??=0;a.turns??=0;a.hitCount??=0;a.regen??=0;a.critical??=0;a.criticalDamage??=0;a.evasion??=0;a.hpBonus??=0;return a;}
function event(s,name,text,api){s.battle.abilityEvents??=[];s.battle.abilityEvents.push({name,text});api.log(s,'player','[능력] '+name+' · '+text);}
function gainAttr(a,key,n){const k=keys[key]||key;a.attributes[k]=(a.attributes[k]||0)+n;}
function damage(s,n,name,api){const value=Math.min(s.battle.enemy.hp,Math.max(0,Math.round(n)));s.battle.enemy.hp-=value;api.emit(s,'skill','ability','enemy',name,value);return value;}
function haste(a,n){a.haste+=n;while(a.haste>=100){a.haste-=100;a.bonusActions=Math.min(3,a.bonusActions+1);}}
export function startAbilities(s,api){const a=state(s);for(const {name,p,v}of abilityProfiles(s)){
 if(p.attribute)gainAttr(a,p.attribute,p.fixed||v);if(p.critical){if(p.critCharges)a.forceCritCharges=p.critCharges;else a.critical+=p.critical*(p.fixed||v);}if(p.criticalDamage)a.criticalDamage+=p.criticalDamage*v;if(p.evasion){if(p.dodgeCharges)a.evasionTemporary=p.evasion;else a.evasion+=p.evasion*(p.fixed||v);}if(p.armor)a.armor+=p.armor*v;if(p.reduction)a.reduction+=p.reduction;if(p.maxHp){a.hpBonus+=v;if(p.healStart)s.hp=Math.min(api.maxHp(s),s.hp+v);}if(p.opening){const count=Math.floor(p.opening*v);a.opening=Math.max(a.opening,count);a.untilFirstHit=!!p.untilFirstHit;}if(p.openingGuard)s.battle.playerShield+=v;if(p.openingVulnerable)a.vulnerable+=v;if(p.startStatus)applyStatus(s,'enemy',p.startStatus,{stacks:p.startStacks||Math.max(1,Math.ceil(v/8)),extend:true});if(p.selfStatus)applyStatus(s,'player',p.selfStatus,{stacks:p.selfStacks,extend:true});if(p.startDamage)damage(s,p.startDamage,name,api);if(p.startStun)s.battle.enemy.stun=Math.max(s.battle.enemy.stun||0,p.startStun);if(p.firstHit)a.firstHit=(a.firstHit||0)+p.firstHit;if(p.unstoppable)a.unstoppable=p.unstoppable;if(p.invulnerable)a.invulnerable=p.invulnerable;if(p.absoluteDodge)a.absoluteDodge=p.absoluteDodge;if(p.guaranteedCrit)a.guaranteedCrit=1;if(p.critCharges&&p.critDamageOnce){a.critDamageCharges=p.critCharges;a.critDamagePerCharge=p.critDamageOnce;}if(p.dodgeCharges)a.dodgeCharges=p.dodgeCharges;if(p.critDamageOnce&&!p.critCharges)a.critDamageOnce=p.critDamageOnce;if(p.revive)a.revive=p.revive;if(p.coreDamage)a.coreDamage=p.coreDamage;if(p.calmReduction)a.calmReduction=p.calmReduction;if(p.openingWeaken){s.battle.enemy.abilityWeaken=p.openingWeaken;a.weakenDecay=!!p.weakenDecay;}
 }if(a.opening>0){s.battle.first='player';s.battle.actor='player';}s.hp=Math.min(api.maxHp(s),s.hp);}
export function beforeAbilityTurn(s,api){const a=state(s);a.turns++;a.extraHit=0;if(a.temporaryStrength){gainAttr(a,'strength',-a.temporaryStrength);a.temporaryStrength=0;}for(const {name,p,v}of abilityProfiles(s)){const due=p.atTurn?a.turns===p.atTurn:p.every?a.turns%p.every===0:false;if(p.chance&&api.random(s.battle)>=p.chance)continue;if(!(due||p.chance))continue;let changed=false;if(p.calmReduction){a.calmReduction=p.calmReduction;changed=true;}
 if(p.temporaryStrength){gainAttr(a,'strength',p.temporaryStrength);a.temporaryStrength=p.temporaryStrength;changed=true;}if(p.growAttribute){gainAttr(a,p.growAttribute,p.growGain);changed=true;}if(p.criticalGrow){a.critical+=p.criticalGrow;changed=true;}if(p.criticalDamageGrow){a.criticalDamage+=p.criticalDamageGrow;changed=true;}if(p.poison){applyStatus(s,'enemy','poison',{stacks:Math.max(1,Math.ceil(v/4)),extend:true});changed=true;}if(p.burn){applyStatus(s,'enemy','burn',{stacks:p.burn,extend:true});changed=true;}if(p.bleed){applyStatus(s,'enemy','bleed',{stacks:p.bleed,extend:true});changed=true;}if(p.stun){s.battle.enemy.stun=p.stun;changed=true;}if(p.haste){haste(a,p.haste*v*25);changed=true;}if(p.damage){damage(s,p.damage,name,api);changed=true;}if(p.maxHpGrow){a.hpBonus+=p.maxHpGrow;changed=true;}if(p.heal){s.hp=Math.min(api.maxHp(s),s.hp+Math.floor(p.heal*statusModifiers(s,'player').healing));changed=true;}if(p.energy){s.energy=Math.min(api.maxEnergy(s),s.energy+p.energy);changed=true;}if(p.shield){s.battle.playerShield+=p.shield;if(p.barrier){a.barrier=true;a.reduction+=.03;}changed=true;}if(p.armorGrow){a.armor+=p.armorGrow;changed=true;}if(p.reductionGain){a.reduction=Math.min(.9,a.reduction+p.reductionGain);changed=true;}if(p.weaken){s.battle.enemy.abilityWeaken=(s.battle.enemy.abilityWeaken||0)+Math.max(1,Math.ceil(p.weaken*v));changed=true;}if(p.vulnerable){a.vulnerable+=p.vulnerable;changed=true;}if(p.guaranteedCrit){a.guaranteedCrit=1;changed=true;}if(p.critDamageOnce){a.critDamageOnce=p.critDamageOnce;changed=true;}if(p.judgment){a.judgment=(a.judgment||0)+p.judgment;changed=true;}if(p.absoluteDodge){a.absoluteDodge=p.absoluteDodge;changed=true;}if(p.extraHit){a.extraHit=p.extraHit;changed=true;}if(changed)event(s,name,'자동 효과 발동',api);
 }if(a.weakenDecay)s.battle.enemy.abilityWeaken=Math.max(0,(s.battle.enemy.abilityWeaken||0)-1);}
export function abilityHit(s,dealt,api){if(dealt<=0)return;const a=state(s);a.hitCount++;if(a.untilFirstHit)a.opening=0;for(const {name,p,v}of abilityProfiles(s)){if(p.hitAttribute)gainAttr(a,p.hitAttribute,p.hitGain);if(p.hitHaste)haste(a,p.hitHaste);if(p.hitBleed)applyStatus(s,'enemy','bleed',{stacks:Math.max(1,Math.ceil(v/2)),extend:true});if(p.hitSpecial)damage(s,p.hitSpecial,name,api);if(p.hitWeaken)s.battle.enemy.abilityWeaken=(s.battle.enemy.abilityWeaken||0)+p.hitWeaken;if(p.hitVulnerable)a.vulnerable+=p.hitVulnerable;if(p.hitMaxHp)a.hpBonus+=p.hitMaxHp;if(p.hitHeal)s.hp=Math.min(api.maxHp(s),s.hp+Math.floor(p.hitHeal*statusModifiers(s,'player').healing));if(p.hitImpact){a.impact=(a.impact||0)+v;if(a.impact>=10){a.impact-=10;s.battle.enemy.stun=1;}}}if(a.judgment){damage(s,a.judgment,'심판',api);a.judgment=0;}if(a.extraHit){damage(s,a.extraHit,'포착',api);a.extraHit=0;}}
export function abilityHurt(s,dealt,api){if(dealt<=0)return;const a=state(s);if(a.barrier)a.reduction=Math.max(0,a.reduction-.02);for(const {name,p}of abilityProfiles(s)){if(p.hurtAttribute)gainAttr(a,p.hurtAttribute,p.hurtGain);if(p.decayOnHurt)gainAttr(a,p.attribute,-Math.min(p.decayOnHurt,a.attributes[keys[p.attribute]]||0));if(p.hurtSpecial)damage(s,p.hurtSpecial,name,api);}if(s.hp<=0&&a.revive&&!a.revived){a.revived=true;s.hp=Math.min(api.maxHp(s),a.revive);event(s,'구원','체력 소진에서 살아남음',api);}}
export function abilityCritBonus(s){return state(s).critical;}
export function abilityEvadeBonus(s){if(s.scene!=='battle'||!s.battle)return 0;const a=state(s);return a.evasion+(a.dodgeCharges>0?a.evasionTemporary||0:0);}
export function abilityDamageBonus(s,power,critical){const a=state(s);let amount=power*(1+Math.min(2,a.vulnerable*.03));if(a.firstHit){amount+=a.firstHit;a.firstHit=0;}if(critical){amount=amount*(1.6+a.criticalDamage+(a.critDamageOnce||0)+(a.critDamageCharges>0?a.critDamagePerCharge||0:0));if(a.critDamageCharges>0)a.critDamageCharges--;if(a.critDamageOnce)a.critDamageOnce=0;}return amount;}
export function abilityMitigation(s,power){const a=state(s);if(a.invulnerable>0){a.invulnerable--;return 0;}return Math.max(0,Math.round((power-a.armor)*(1-Math.min(.95,a.reduction+(!a.lastDirectAttack?a.calmReduction||0:0)))));}
export function skipEnemyForAbility(s){const a=state(s);if(a.opening>0){a.opening--;if(a.opening>0)return true;}if(a.bonusActions>0){a.bonusActions--;return true;}return false;}
export function forceAbilityCritical(s){const a=state(s);if(a.guaranteedCrit>0){a.guaranteedCrit--;return true;}if(a.forceCritCharges>0){a.forceCritCharges--;return true;}return false;}
export function forceAbilityDodge(s){const a=state(s);if(a.absoluteDodge>0){a.absoluteDodge--;return true;}return false;}
export function consumeDodgeOpportunity(s){const a=state(s);if(a.dodgeCharges>0)a.dodgeCharges--;}
